<script setup lang="ts">
import{computed}from'vue';import{TrendingUp}from'lucide-vue-next';import{time,percent}from'../../utils/format';const props=defineProps<{history:{time:string;progress:number}[]}>();const points=computed(()=>props.history.map((p,i)=>`${20+i/Math.max(1,props.history.length-1)*560},${115-p.progress}`).join(' '));
</script>
<template><section class="panel history-panel"><div class="panel-heading"><div><h2>Evolução da apuração</h2><p>Seções totalizadas ao longo desta consulta</p></div><TrendingUp :size="20"/></div><div v-if="history.length<2" class="history-wait"><div class="history-point"></div><span>{{history.length?percent(history[0].progress)+' na primeira leitura':'Aguardando a primeira leitura'}}</span><small>O gráfico será traçado quando o TSE publicar uma nova atualização.</small></div><template v-else><svg class="history-chart" viewBox="0 0 600 140" role="img" aria-label="Evolução do percentual de seções totalizadas"><path d="M20 15H580M20 65H580M20 115H580" stroke="var(--border)" stroke-dasharray="4 4"/><polyline :points="points" fill="none" stroke="#39749f" stroke-width="3"/><circle v-for="(p,i) in history" :key="p.time" :cx="20+i/Math.max(1,history.length-1)*560" :cy="115-p.progress" r="3" fill="#39749f"><title>{{time(p.time)}}: {{percent(p.progress)}}</title></circle></svg><div class="chart-labels"><span>{{time(history[0].time)}}</span><span>{{time(history.at(-1)?.time)}}</span></div></template><div class="panel-footnote">Histórico observado nesta sessão; não representa períodos anteriores.</div></section></template>
